<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Shared\Exception\ConstraintException;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetTemplateVO;
use Civi\Lughauth\Features\Document\Template\Domain\TemplateRef;

final class TemplateAssetTemplateVOUnitTest extends TestCase
{
    public function test_asignation_keep_value(): void
    {
        $value = new TemplateRef('one');
        $ref = TemplateAssetTemplateVO::from($value);
        $this->assertEquals(new TemplateRef('one'), $ref->value());
        $other = TemplateAssetTemplateVO::tryFrom($ref, new ConstraintFailList());
        $this->assertSame($other, $ref);
        $more = TemplateAssetTemplateVO::from($ref);
        $this->assertSame($more, $ref);
    }
    public function test_asignation_invalid_type(): void
    {
        $errors = new ConstraintFailList();
        $other = TemplateAssetTemplateVO::tryFrom('1', $errors);
        $this->assertNull($other);
        $this->assertTrue($errors->hasErrors());
    }
    public function test_optimist_asignation_invalid_type(): void
    {
        $this->expectException(ConstraintException::class);
        $method = new ReflectionMethod(TemplateAssetTemplateVO::class, 'fromUnsafe');
        $method->invoke(null, [11, "bad"]);
    }
    public function test_equals(): void
    {
        $one = TemplateAssetTemplateVO::from(new TemplateRef('one'));
        $same = TemplateAssetTemplateVO::from(new TemplateRef('one'));
        $other = TemplateAssetTemplateVO::from(new TemplateRef('other'));
        $withEmpty = $one->equals(null);
        $withSame = $one->equals($same);
        $withOther = $one->equals($other);

        $this->assertFalse($withEmpty);
        $this->assertTrue($withSame);
        $this->assertFalse($withOther);
    }
}
